import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.math.BigDecimal;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
class CheckoutApplicationTests {

    @Autowired
    private CheckoutService checkoutService;

    @Test
    void exemplo1() {
        CheckoutRequest request = new CheckoutRequest(
            List.of(
                new ItemCarrinho("Camiseta", new BigDecimal("79.90"), 2, new BigDecimal("0.30")),
                new ItemCarrinho("Tênis", new BigDecimal("249.90"), 1, new BigDecimal("1.20"))
            ),
            "EXPRESSA",
            "BEMVINDO10",
            "PIX",
            null,
            "BRONZE",
            "NORTE"
        );

        ResponseEntity<Map> response = restTemplate.postForEntity("/checkout/resumo", request, Map.class);
        assertEquals(HttpStatus.OK, response.getStatusCode());
        Map<String, Object> body = response.getBody();

        assertEquals(409.70, body.get("subtotalProdutos"));
        assertEquals(40.97, body.get("descontoCupom"));
        assertEquals(33.10, body.get("frete"));
        assertEquals(2, body.get("prazoEntregaDias"));
        assertEquals(10.24, body.get("seguro"));
        assertEquals(-20.60, body.get("ajustePagamento"));
        assertEquals(391.47, body.get("totalFinal"));
        assertEquals(1, body.get("parcelas"));
        assertEquals(391.47, body.get("valorParcela"));
        assertEquals(0.00, body.get("creditoProximaCompra"));
        assertEquals(false, body.get("brinde"));
    }

    @Test
    void exemplo2() {
