            "CARTAO",
            6,
            "PRATA",
            "CENTRO_OESTE"
        );

        ResponseEntity<Map> response = restTemplate.postForEntity("/checkout/resumo", request, Map.class);
        assertEquals(HttpStatus.OK, response.getStatusCode());
        Map<String, Object> body = response.getBody();

        assertEquals(409.70, body.get("subtotalProdutos"));
        assertEquals(0.00, body.get("descontoCupom"));
        assertEquals(15.60, body.get("frete"));
        assertEquals(7, body.get("prazoEntregaDias"));
        assertEquals(6.15, body.get("seguro"));
        assertEquals(30.55, body.get("ajustePagamento"));
        assertEquals(462.00, body.get("totalFinal"));
        assertEquals(6, body.get("parcelas"));
        assertEquals(77.00, body.get("valorParcela"));
        assertEquals(8.19, body.get("creditoProximaCompra"));
        assertEquals(false, body.get("brinde"));
    }

